style.css:
@-moz-document domain("mail.google.com") {
/* =====================================
   ? Pookie Sakura Gmail Theme
======================================*/

/* Soft Pink Background */

body,
.nH,
.aAU,
.aeF,
.ar4,
.Bu{
    background:
    radial-gradient(circle at top,#fff8fc,#ffeaf4,#ffdce9) !important;
}

/* Sidebar */

.aeN,
.TK,
.aim,
.nM{
    background:rgba(255,255,255,.65)!important;
    backdrop-filter:blur(18px);
    border-radius:22px;
}

/* Header */

header,
.gb{
    background:rgba(255,255,255,.55)!important;
    backdrop-filter:blur(18px);
}

/* Compose Button */

.T-I.T-I-KE,
div[gh="cm"]{
    background:linear-gradient(135deg,#ff78ba,#ff9ccc)!important;
    color:white!important;
    border-radius:40px!important;
    border:none!important;
    box-shadow:0 8px 25px rgba(255,105,180,.3);
}

/* Email Cards */

.zA{
    background:rgba(255,255,255,.75)!important;
    border-radius:18px!important;
    margin:6px 10px!important;
    transition:.3s;
}

.zA:hover{
    background:#ffe3ef!important;
    transform:scale(1.01);
}

/* Reading Mail */

.a3s{
    background:rgba(255,255,255,.82)!important;
    border-radius:20px!important;
    padding:25px!important;
}

/* Scrollbar */

::-webkit-scrollbar{
width:10px;
}

::-webkit-scrollbar-thumb{
background:#ff9bc9;
border-radius:20px;
}

::-webkit-scrollbar-track{
background:#fff3f8;
}

/* Sakura Background */

body::before{

content:"? ? ? ? ? ? ? ? ? ? ? ? ? ?";

position:fixed;

left:-5%;

top:-10%;

width:120%;

height:120%;

font-size:28px;

line-height:90px;

pointer-events:none;

opacity:.22;

animation:sakuraFall 35s linear infinite;

z-index:999999;
}

@keyframes sakuraFall{

0%{
transform:translateY(-100px) translateX(0) rotate(0deg);
}

50%{
transform:translateY(50vh) translateX(60px) rotate(180deg);
}

100%{
transform:translateY(110vh) translateX(-40px) rotate(360deg);
}

}

/* Cute Pink Selection */

::selection{
background:#ffaad4;
color:white;
}

/* Rounded Panels */

div[role="main"],
div[role="navigation"]{
border-radius:20px;
}

/* Smooth */

*{
transition:.2s;
}
}
